        iframe.allowFullscreen = true

        videoItem.appendChild(iframe)
        carousel.appendChild(videoItem)
      })

      videosSection.appendChild(carousel)
      basicDescription.prepend(videosSection)
    })
  },
  100
) // 100ms delay

